INSERT INTO desmos_solutions (question_id, state_json, credit_name, source, source_fingerprint, imported_at) SELECT '25da87f8', '{"version":11,"randomSeed":"fc17b309104f483d7dab37e731cb5724","graph":{"viewport":{"xmin":-17.574061609208435,"ymin":-44.130642968276824,"xmax":22.10436038980317,"ymax":26.72368202995812},"__v12ViewportLatexStash":{"xmin":"-17.574061609208435","xmax":"22.10436038980317","ymin":"-44.130642968276824","ymax":"26.72368202995812"}},"expressions":{"list":[{"type":"text","id":"24","text":"there''s definitely multiple ways to solve this, this is how I did it"},{"type":"expression","id":"22","color":"#c74440","latex":"a+a\\sqrt{3}+2a\\sim18+6\\sqrt{3}","residualVariable":"e_{1}","regressionParameters":{"a":6.000000000000001}},{"type":"text","id":"26","text":"a triangle with angles 30,60 and 90 follows special right triangle rule a:a*sqrt3:2a respectively. Since they gave us the perimeter we can set up the regression as such! a is 6, 6*2 is 12. "},{"type":"text","id":"28","text":"In a triangle the largest degree are opposite to the longest side, so in this case 90 and 2a. You should memorize these special right triangles rules."}]},"includeFunctionParametersInRandomSeed":true,"doNotMigrateMovablePointStyle":true}', 'Allen', 'prepzy', 'd6a221575f3f4419340f0a24f190733bc0fb191fe8ef8b979d04664596ace5bc', datetime('now') WHERE EXISTS (SELECT 1 FROM questions WHERE id = '25da87f8') ON CONFLICT(question_id) DO UPDATE SET state_json=excluded.state_json, credit_name=excluded.credit_name, source=excluded.source, source_fingerprint=excluded.source_fingerprint, imported_at=excluded.imported_at WHERE desmos_solutions.state_json IS NOT excluded.state_json OR desmos_solutions.credit_name IS NOT excluded.credit_name OR desmos_solutions.source IS NOT excluded.source OR desmos_solutions.source_fingerprint IS NOT excluded.source_fingerprint;
