INSERT INTO desmos_solutions (question_id, state_json, credit_name, source, source_fingerprint, imported_at) SELECT '2992ac30', '{"version":11,"randomSeed":"7c0ab4834fd30484f5cc44249b4de93c","graph":{"viewport":{"xmin":-10,"ymin":-25,"xmax":10,"ymax":25},"__v12ViewportLatexStash":{"xmin":"-10","xmax":"10","ymin":"-25","ymax":"25"}},"expressions":{"list":[{"type":"expression","id":"1","color":"#c74440","latex":"p\\left(t\\right)=260\\left(1.04\\right)^{\\left(\\frac{6}{4}\\right)t}"},{"type":"expression","id":"2","color":"#2d70b3","latex":"p\\left(0\\right)"},{"type":"text","id":"16","text":"p of 0 is the baseline population"},{"type":"expression","id":"3","color":"#388c46","latex":"p\\left(1\\right)"},{"type":"text","id":"15","text":"p(1) is the population after one year"},{"type":"expression","id":"4","color":"#6042a6","latex":"260\\cdot x_{1}\\sim p\\left(1\\right)","residualVariable":"e_{1}","regressionParameters":{"x_{1}":1.0605960588272993}},{"type":"text","id":"22","text":"above regression finds population increase rate per year (after doing x1-1 that is)"},{"type":"expression","id":"20","color":"#2d70b3"},{"type":"expression","id":"5","color":"#000000","latex":"x_{1}-1"},{"type":"expression","id":"6","color":"#c74440","latex":"p_{e}=0.0605960588273\\cdot100"},{"type":"text","id":"23","text":"P_e is the percentage increase of population"},{"type":"expression","id":"24","color":"#6042a6"},{"type":"expression","id":"9","color":"#6042a6","latex":"p_{m}=\\frac{p_{e}}{12}"},{"type":"text","id":"26","text":"12 months in a year so p_e/12 gives us percentage average percentage increase per month"},{"type":"expression","id":"10","color":"#000000","latex":"p_{m}n\\sim4","residualVariable":"e_{m}","regressionParameters":{"n":7.921307248182752}},{"type":"text","id":"28","text":"so we know percentage increase per month and we need to find how many months worth of percentage increase is 4% so increase per month muliplied by n ~ 4 solving for 9 by regression "},{"type":"expr